```objc
    if (alert) {
      if (@available(iOS 14, *)) {
        presentationOptions |=
            UNNotificationPresentationOptionList | UNNotificationPresentationOptionBanner;
      } else {
        presentationOptions |= UNNotificationPresentationOptionAlert;
      }
    }
```
